raw:
{
  "spells": [
    {
      "id": "spell_fire_10",
      "theory": "炉膛鼓焰作用于已经点燃的炉火，将魔力沿热流推入柴薪间隙，使火焰在短时间内烧得更旺。它不凭空生火，也不改变燃料种类；受术炉膛仍要投入正常分量的木柴或炭块。魔力只在已有火焰与燃料接触处流转，离开炉膛便迅速散去，因此对露天篝火同样有效，却不能让湿柴自行干燥。",
      "casting": "面朝炉膛张开五指，缓慢推入一股魔力，同时用另一只手轻拨火钳翻动柴薪。待火舌由黄转白再收回手掌，整个过程需保持呼吸平稳。",
      "failure": "魔力推送过急时，火焰会猛地蹿高又塌落，在炉壁上留下大片烟熏痕迹。翻柴不当可能压灭局部火头，使炉温骤降，已投入的燃料只剩余烟，需要重新引火。",
      "counters": [
        "抽走炉膛附近柴薪或泼入少量水，火势便回落至普通水平。",
        "用铁板隔断火焰与魔力推入方向，鼓焰效果明显减弱。"
      ],
      "socialConsequences": "铁匠与陶工在赶工时愿意请人鼓焰，尤其在锻打小件或烧制薄坯时。卖柴人担心炉温效率提高会减少单次用柴量，却也知道旺火能承接更多急件。乡约见证的民事承诺若涉及借用他人炉膛，通常要求施术者只按约定时段施为，不得把火势维持到邻家烟囱冒烟为止。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时火势起伏不稳，需反复拨柴维持。",
        "掌握节奏后，火焰能均匀铺满炉膛底部。",
        "熟练者可在不掀翻柴堆的前提下调整火舌方向。",
        "更高熟练度使炉温稳定，仍受原有燃料分量限制。"
      ]
    },
    {
      "id": "spell_fire_11",
      "theory": "隔焰罩在受术者衣物外层织出一层薄薄的魔力膜，膜面沿身体轮廓流动，遇到外来火焰时将其热量偏转开。它不改变火焰本身，也不阻挡刀剑、箭矢或落石。膜层依附在受术者身上，离开身体约一拳便失去作用，因此无法为身旁同伴提供遮蔽。",
      "casting": "以指尖沿受术者肩头划一道弧线，再顺势绕至腰侧收拢，同时低声念出短促音节。膜层成形时会有轻微凉意，受术者应站定不动。",
      "failure": "弧线划得过快时，膜层只覆盖半边身体，另一侧仍会被火焰灼伤。收拢不当会让膜面起皱，受术者活动时可能自行撕裂，凉意消失后便不再偏转热量。",
      "counters": [
        "用长杆挑开受术者衣物，膜层随布料脱离身体即失效。",
        "持续泼水浸湿衣物，膜面被水膜覆盖后偏转效果减弱。"
      ],
      "socialConsequences": "走夜路的商贩和看守灯塔的工人愿意在靠近火盆时请人施罩，尤其搬运油料或经过厨房通道时。公会许可的施术者可在城市工坊内为学徒加护，但须由工坊主在场确认只用于防护。港务规定追究航运事故时，若货损由火灾引起，是否施过隔焰罩会成为责任划分的参考，却不会替代对纵火行为的追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时膜层薄厚不均，凉意时断时续。",
        "掌握划弧后，膜层能完整覆盖躯干与四肢。",
        "熟练者可在受术者行走中维持膜面不裂。",
        "更高熟练度使偏转更平稳，仍不抵挡刀剑冲击。"
      ]
    },
    {
      "id": "spell_fire_12",
      "theory": "熔缝术以铁料为引，将魔力集中到金属裂缝两侧，使填料与母材在热流中重新接合。它只能填补已有裂缝，不能凭空造出缺失的部件，也不能改变金属种类。铁料与树脂须在施术时实际存在并投入裂缝，冷却后接合处仍保留原有金属的硬度，但承受拉力不如完整锻件。",
      "casting": "将铁料按入裂缝，另一手持树脂沿缝口涂抹，再以掌心贴住接合处缓缓送入魔力。待铁料由暗红转为灰白，方可移开手掌。",
      "failure": "魔力送入过快会使填料外溢，在金属表面结出脆硬瘤块，一敲即碎。树脂涂抹不均则接合处留下气孔，冷却后裂缝虽被遮住，受力时仍会从原处重新裂开。",
      "counters": [
        "用湿布覆盖接合处使其骤冷，填料与母材无法咬合。",
        "撬动裂缝两侧使填料错位，接合处便失去承力作用。"
      ],
      "socialConsequences": "铁匠铺和船坞愿意请人修补铁箍、锅沿与锚链环，尤其在不便重铸大件时。卖新铁器的商人担心修补生意分流客源，却也知道有些旧件只值得补而不值得换。港务规定追究货损时，若修复过的金属件在航运中再次开裂，施术者与委托方须各自说明用料和操作，公会许可记录可作凭据。",
      "law": {
        "river": "consent",
        "city": "consent",
        "port": "consent"
      },
      "proficiencyEffects": [
        "低熟练度时填料常外溢，需事后打磨修整。",
        "掌握送魔节奏后，接合处气孔明显减少。",
        "熟练者能沿细长裂缝均匀填料而不烫伤母材。",
        "更高熟练度使接合更平整，仍不能创造缺失部件。"
      ]
    }
  ]
}
